void BsimcmgGenModel::setInstanceParam(const std::string& name, double value) {
    setModelParam(name, value);
}

void BsimcmgGenModel::stamp_pattern(StampPattern& out) const {
    for (const auto& [r, c] : jacPattern_) {
        if (r < nodes_.size() && c < nodes_.size())
            out.entries.emplace_back(nodes_[r], nodes_[c]);
    }
}

